from enum import Enum

class Belnap(Enum):
    F = "F"; N = "N"; B = "B"; T = "T"

def tmeet(a, b):
    F, N, B, T = Belnap.F, Belnap.N, Belnap.B, Belnap.T
    table = {(F,F):F,(F,N):F,(F,B):F,(F,T):F,(N,F):F,(N,N):N,(N,B):F,(N,T):N,
             (B,F):F,(B,N):F,(B,B):B,(B,T):B,(T,F):F,(T,N):N,(T,B):B,(T,T):T}
    return table[(a,b)]

def tjoin(a, b):
    F, N, B, T = Belnap.F, Belnap.N, Belnap.B, Belnap.T
    table = {(F,F):F,(F,N):N,(F,B):B,(F,T):T,(N,F):N,(N,N):N,(N,B):T,(N,T):T,
             (B,F):B,(B,N):T,(B,B):B,(B,T):T,(T,F):T,(T,N):T,(T,B):T,(T,T):T}
    return table[(a,b)]

vals = list(Belnap)
for a in vals:
    for b in vals:
        assert tmeet(a,b) == tmeet(b,a), "meet commutativity"
        assert tjoin(a,b) == tjoin(b,a), "join commutativity"
print("Commutativity verified")

for a in vals:
    for b in vals:
        for c in vals:
            assert tmeet(a, tmeet(b,c)) == tmeet(tmeet(a,b), c)
            assert tjoin(a, tjoin(b,c)) == tjoin(tjoin(a,b), c)
            lhs = tmeet(a, tjoin(b,c))
            rhs = tjoin(tmeet(a,b), tmeet(a,c))
            assert lhs == rhs, f"distributivity fails: {a},{b},{c}"
print("Associativity and distributivity verified (64 cases)")

for a in vals:
    assert tmeet(Belnap.F, a) == Belnap.F
    assert tmeet(a, Belnap.T) == a
print("Bounded: F is bottom, T is top")

