from enum import Enum

class Belnap(Enum):
    F = "F"; N = "N"; B = "B"; T = "T"

def tmeet(a, b):
    F, N, B, T = Belnap.F, Belnap.N, Belnap.B, Belnap.T
    table = {(F,F):F,(F,N):F,(F,B):F,(F,T):F,(N,F):F,(N,N):N,(N,B):F,(N,T):N,
             (B,F):F,(B,N):F,(B,B):B,(B,T):B,(T,F):F,(T,N):N,(T,B):B,(T,T):T}
    return table[(a,b)]

def bneg(a):
    return {Belnap.T: Belnap.F, Belnap.F: Belnap.T, Belnap.B: Belnap.B, Belnap.N: Belnap.N}[a]

def designated(a): return a in (Belnap.T, Belnap.B)
def is_glut(a): return designated(a) and designated(bneg(a))

# Forward: explosion failure => glut exists
explosion_fails = any(
    designated(tmeet(p, bneg(p))) and any(not designated(q) for q in Belnap)
    for p in Belnap
)
glut_exists = any(is_glut(v) for v in Belnap)

print(f"Explosion fails: {explosion_fails}")
print(f"Glut exists: {glut_exists}")
print(f"Equivalence holds: {explosion_fails == glut_exists}")
print(f"\nGluts: {[v.value for v in Belnap if is_glut(v)]}")
print(f"Gaps: {[v.value for v in Belnap if not designated(v) and not designated(bneg(v))]}")

